INSERT INTO `lifestyle_tip` (`trigger_field`, `trigger_value`, `category`, `title`, `tip_text`, `source`, `priority`) VALUES
('risk_category', 'always', 'nutrition_general', 'General Heart-Healthy Eating Pattern', 'Build meals around fruits, vegetables, whole grains, healthy proteins and plant oils. Choose minimally processed foods and keep added sugar and salt low.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#heart_healthy_eating_pattern', 9),
('risk_category', 'always', 'healthy_plate', 'Malaysian Healthy Plate Quarter Quarter Half', 'At meals, fill one quarter of the plate with carbohydrate foods, one quarter with protein, and half with fruits and vegetables. Choose plain water instead of sugary drinks.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#malaysian_healthy_plate_quarter_quarter_half', 9),
('risk_category', 'always', 'fruit_veg_fibre', 'Fruits, Vegetables, Fibre and Plant Foods', 'Aim for five servings of fruits and vegetables daily. Prefer whole produce, legumes and whole grains to help reach about 20–30 g of fibre a day.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#fruits_vegetables_fibre_plant_foods', 8),
('risk_category', 'always', 'healthy_protein', 'Fish, Lean Protein and Plant Protein', 'Choose fish, seafood, beans, lentils, tofu and tempe more often. If eating meat or poultry, choose lean cuts and avoid processed meats.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#fish_lean_protein_plant_protein', 8),
('risk_category', 'always', 'minimally_processed', 'Minimally Processed versus Ultra-Processed Foods', 'Base daily eating on fresh or minimally processed foods. Limit ultra-processed products that are often high in salt, sugar and unhealthy fats.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#minimally_vs_ultra_processed_foods', 7),
('risk_category', 'always', 'malaysian_food_choices', 'Malaysian-Friendly Food Choices and Substitutions', 'Choose more steamed, grilled, soup-based and home-cooked Malaysian meals. Have fried, santan-rich and highly processed dishes less often.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#malaysian_friendly_food_choices', 8),
('high_salt', 'yes', 'salt_reduction', 'Salt and Sodium Reduction', 'Reduce salt by tasting food before adding sauces, using less salty condiments and choosing fresh foods. Limit processed, preserved and instant foods.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#salt_and_sodium_reduction', 10),
('risk_category', 'always', 'saturated_fat', 'Saturated Fat Guidance', 'Limit foods high in saturated fat such as fatty meat, skin-on poultry, full-fat dairy, butter and coconut-based dishes. Choose healthier fats and leaner options more often.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#saturated_fat_guidance', 8),
('risk_category', 'always', 'trans_fat', 'Trans Fat Guidance', 'Avoid foods containing industrial trans fats, including products made with partially hydrogenated oils. Check labels and choose less processed alternatives.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#trans_fat_guidance', 8),
('risk_category', 'always', 'healthy_cooking_fats', 'Unsaturated Fats and Cooking Methods', 'Use liquid plant oils such as canola, sunflower, corn, peanut or olive oil in small amounts. Prefer steaming, grilling, baking and stir-frying over deep-frying.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#unsaturated_fats_and_cooking_methods', 7),
('high_cholesterol', 'yes', 'dietary_cholesterol', 'Dietary Cholesterol Guidance', 'Focus on the overall diet: increase fibre-rich plant foods and limit saturated and trans fats. Discuss individual dietary changes with a clinician or dietitian when needed.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#dietary_cholesterol_guidance', 7),
('high_sugar_diet', 'yes', 'sugar_reduction', 'Added Sugar and Sweetened Drinks', 'Choose plain water most often and reduce sweetened drinks, desserts and foods with added sugar. Limit sugary treats to occasional portions.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#added_sugar_and_sweetened_drinks', 9),
('risk_category', 'always', 'weight_management', 'Portion Control and Weight Management', 'Use sensible portions, eat slowly and stop before feeling completely full. Build regular meals around vegetables, fruit, whole grains and healthy protein.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#portion_control_and_weight_management', 9),
('low_activity', 'yes', 'physical_activity', 'General Physical Activity Targets', 'Work toward regular physical activity that suits your ability. Break activity into manageable sessions and discuss a safe plan with a clinician if you have a medical condition.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#general_physical_activity_targets', 9),
('low_activity', 'yes', 'aerobic_activity', 'Aerobic Exercise Guidance', 'Choose enjoyable aerobic activities such as walking, cycling or swimming. Start at a comfortable pace and increase gradually as tolerated.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#aerobic_exercise_guidance', 8),
('low_activity', 'yes', 'strength_activity', 'Strength or Resistance Activity', 'Include suitable muscle-strengthening activities on regular days, using safe movements and proper technique. Seek professional guidance if unsure.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#strength_resistance_activity', 7),
('sedentary', 'yes', 'reduce_sitting', 'Reducing Sedentary Time', 'Break up long periods of sitting by standing, stretching or walking regularly through the day. Small movement breaks add up.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#reducing_sedentary_time', 7),
('low_activity', 'yes', 'activity_progression', 'Gradual Activity Progression', 'Begin with short, comfortable activity sessions and increase duration or intensity slowly. Consistency is more important than doing too much too soon.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#gradual_activity_progression', 7),
('risk_category', 'always', 'exercise_safety', 'Exercise Safety Precautions', 'Stop exercise and seek medical advice for concerning symptoms such as chest pain, severe breathlessness, dizziness or fainting. Follow personalised medical advice.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#exercise_safety_precautions', 10),
('smoker', 'yes', 'tobacco_cessation', 'Smoking and Tobacco Cessation', 'Stopping smoking and avoiding tobacco are among the strongest actions for heart health. Seek support from a healthcare professional or cessation service.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#smoking_and_tobacco_cessation', 10),
('risk_category', 'always', 'sleep', 'Sleep for Heart Health', 'Keep a regular sleep routine and aim for adequate, good-quality sleep. Discuss persistent sleep problems, loud snoring or daytime sleepiness with a clinician.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#sleep_for_heart_health', 7),
('risk_category', 'always', 'stress_management', 'Stress Management for Heart Health', 'Use practical stress-management habits such as regular movement, relaxation, social support and a consistent routine. Ask for professional support when stress feels unmanageable.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#stress_management_for_heart_health', 6),
('high_bp', 'yes', 'blood_pressure', 'Blood Pressure Lifestyle Management', 'Support healthy blood pressure with lower-salt eating, regular activity, a healthy weight, no tobacco and limited alcohol. Continue prescribed care and monitoring.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#blood_pressure_lifestyle_management', 9),
('high_cholesterol', 'yes', 'cholesterol', 'Cholesterol Lifestyle Management', 'Support cholesterol control with more fibre-rich plant foods, healthier fats and regular activity. Continue prescribed treatment and follow-up with your healthcare team.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#cholesterol_lifestyle_management', 9),
('diabetes', 'yes', 'diabetes_cvd', 'Blood Glucose and Diabetes-Related Cardiovascular Lifestyle', 'Choose high-fibre foods, reduce sugary drinks and refined carbohydrates, and stay active within your care plan. Diabetes management should be personalised with your healthcare team.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#blood_glucose_diabetes_cardiovascular_lifestyle', 8),
('heart_attack_history', 'yes', 'post_heart_attack', 'Lifestyle After a Heart Attack', 'After a heart attack, follow your cardiac-care plan, take medicines as prescribed and join rehabilitation if offered. Activity and diet plans should be individually supervised.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#lifestyle_after_heart_attack', 9),
('heart_failure', 'yes', 'heart_failure', 'Heart Failure Lifestyle and Nutrition', 'For heart failure, follow your clinician\'s personalised advice about food, salt, fluids, medicines and activity. Report worsening symptoms promptly.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#heart_failure_lifestyle_and_nutrition', 10),
('heart_disease', 'yes', 'cardiac_rehabilitation', 'Cardiac Rehabilitation Programme', 'Ask your healthcare team whether cardiac rehabilitation is suitable. It can provide supervised activity, education and support after heart-related illness or treatment.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#cardiac_rehabilitation_programme', 9),
('heart_disease', 'yes', 'existing_cvd', 'Existing Coronary or Cardiovascular Disease Lifestyle', 'With diagnosed cardiovascular disease, follow personalised medical advice, attend follow-up and use lifestyle changes alongside—not instead of—prescribed treatment.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#existing_coronary_cardiovascular_disease_lifestyle', 8),
('risk_category', 'always', 'habit_building', 'Practical Habit-Building Suggestions', 'Choose one realistic heart-healthy change at a time, make it part of your routine and build gradually. Small consistent habits are more sustainable.', 'cardiovascular_nutrition_lifestyle_guidelines_structured.md#practical_habit_building_suggestions', 7);
