-- FutureWell ERD-conformant data import for phpMyAdmin/MySQL.
-- Select the target database in phpMyAdmin before importing.
-- This script recreates only the three ERD reference tables; it stores no user health records.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `lifestyle_tip`;
DROP TABLE IF EXISTS `cause_of_death`;
DROP TABLE IF EXISTS `public_clinic`;

CREATE TABLE `lifestyle_tip` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `trigger_field` VARCHAR(40) NOT NULL,
  `trigger_value` VARCHAR(20) NOT NULL,
  `category` VARCHAR(30) NOT NULL,
  `title` VARCHAR(120) NOT NULL,
  `tip_text` VARCHAR(400) NOT NULL,
  `source` VARCHAR(255) NOT NULL,
  `priority` INT NOT NULL DEFAULT 5,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lifestyle_tip_trigger` (`trigger_field`, `trigger_value`, `category`),
  KEY `idx_lifestyle_tip_lookup` (`trigger_field`, `trigger_value`, `priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `cause_of_death` (
  `year` YEAR NOT NULL,
  `age_group` VARCHAR(10) NOT NULL,
  `age_group_order` TINYINT UNSIGNED NOT NULL,
  `sex` VARCHAR(10) NOT NULL,
  `certification` VARCHAR(30) NOT NULL,
  `rank` TINYINT UNSIGNED NOT NULL,
  `cause` VARCHAR(120) NOT NULL,
  `deaths` INT UNSIGNED NOT NULL,
  `percent_of_certification_group` DECIMAL(5,2) NOT NULL,
  `all_causes_deaths` INT UNSIGNED NOT NULL,
  `source_table` VARCHAR(20) NOT NULL,
  `report_page` SMALLINT UNSIGNED NOT NULL,
  `pdf_file_page` SMALLINT UNSIGNED NOT NULL,
  `source_url` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`year`, `age_group`, `sex`, `certification`, `rank`),
  KEY `idx_cod_filter` (`year`, `age_group_order`, `sex`, `rank`),
  KEY `idx_cod_cause` (`cause`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `public_clinic` (
  `facility_code` VARCHAR(20) NOT NULL,
  `facility_name` VARCHAR(120) NOT NULL,
  `facility_type` VARCHAR(80) NOT NULL,
  `state` VARCHAR(50) NOT NULL,
  `district` VARCHAR(80) NOT NULL,
  `address` VARCHAR(500) NULL,
  `postcode` VARCHAR(10) NOT NULL,
  `phone` VARCHAR(60) NULL,
  `latitude` DECIMAL(10,7) NULL,
  `longitude` DECIMAL(10,7) NULL,
  `source_url` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`facility_code`),
  KEY `idx_public_clinic_state_district` (`state`, `district`),
  KEY `idx_public_clinic_type` (`facility_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;











SET FOREIGN_KEY_CHECKS = 1;
